+);
+
+DECLARE_EVENT_CLASS(dpu_uint64_t_data_template,
+		    TP_PROTO(const char *name, u64 data),
+	TP_ARGS(name, data),
+	TP_STRUCT__entry(
+		__string(name_str, name)
+		__field(u64, data)
+	),
+	TP_fast_assign(
