+		if (pmu->init_cpu && (!pmu->cpumask || !cpumask_test_cpu(cpu, pmu->cpumask)))
+			cpumask_migrate = pmu->init_cpu(pmu, cpu);
+		if (cpumask_migrate && !WARN_ON_ONCE(prev_cpu >= nr_cpu_ids))
+			perf_pmu_migrate_context(pmu, prev_cpu, cpu);
+	}
